import sys
import re

def sanitize(s):
    # Removed the hyphen from the negative lookarounds
    p_5_groups = r"(?P<five_plus>(?<![a-zA-Z0-9])(?:\d{4}-){4,}\d{4}(?![a-zA-Z0-9]))"

    p_multi = r"(?P<multi_token>(?<![a-zA-Z0-9])(?:token=){2,}[a-zA-Z0-9]*)"

    p_api = r"(?P<api_token>(?<![a-zA-Z0-9])token=)[a-zA-Z0-9]+(?![a-zA-Z0-9])"

    # Removed the hyphen from the negative lookarounds
    p_card = r"(?P<card>(?<![a-zA-Z0-9])(?:\d{4}-){3}\d{4}(?![a-zA-Z0-9]))"

    pattern = re.compile(f"{p_5_groups}|{p_multi}|{p_api}|{p_card}")

    def repl(m):
        if m.group("five_plus"):
            return m.group("five_plus") 
        elif m.group("multi_token"):
            return m.group("multi_token") 
        elif m.group("api_token"):
            return m.group("api_token") + "[TOKEN_REDACTED]"
        elif m.group("card"):
            return "[CARD_REDACTED]"

    return pattern.sub(repl, s)

n = int(input())
for _ in range(n):
    print(sanitize(input()))
